ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_plan_1"] = {
{"fw_ld5_pharmacy_a001","plan",2,"reg=civilian,family,worker,rescue|day=0,8|hour=8,21|mood=fear",{1,"Mama's heart pills ran out this morning, she's gray as a sheet, swears she's fine",2,"Which ones? She's got a drawer full",1,"Little ones, long name, starts with a D, I can't even say it",2,"Pruitt's keeps it all on file, we give 'em her name--",1,"If they're open! If anybody's in there, what if somebody's in there?!",2,"Then we come back and think of something else, but we TRY, gimme the damn bag"}},
{"fw_ld5_pharmacy_a002","plan",2,"reg=civilian,family,worker,rescue|day=0,8|mood=fear",{1,"Walt's got two vials of insulin left, I counted twice",2,"Nothing stays cold anymore, they're cooking in the bag",1,"So the drugstore, NOW, they keep a stock in back",2,"No, no power, no cold back there either",1,"Then ice! A cooler! Something! I can't sit here counting vials, Jesus"}},
{"fw_ld5_pharmacy_a003","plan",2,"reg=family|day=0,10|mood=fear",{1,"The boy's inhaler's making that empty rattle again",2,"How many puffs today?",1,"I quit counting at nine, he's wheezing in his sleep",2,"Pruitt's is four blocks, I can do four blocks, you stay with him",1,"Take the flashlight, watch your hands, there's glass all over the front"}},
{"fw_ld5_pharmacy_a004","plan",2,"reg=civilian,family,worker,rescue|x2=m|day=0,14|mood=angry",{1,"Hank says Pruitt's got hit already, shelves bare",2,"Don't mean it's empty, NOBODY gets in the back",1,"'Cause it's locked, Cecil, and I ain't got a key, shit",2,"Crowbar's in the garage, ten minutes",1,"And if the pharmacist is back there? I ain't going in first, no sir"}},
{"fw_ld5_pharmacy_a005","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"One in, two out front, like every store since Friday",2,"Why am I the one in?",1,"You worked behind a counter",2,"Nine months in high school, I stocked SHAMPOO"}},
{"fw_ld5_pharmacy_a006","plan",2,"reg=civilian,family,worker,rescue|hour=6,18|mood=sad",{1,"She's stretching the last can of formula with water, fifty fifty",2,"That ain't right, babies need it full--",1,"I KNOW that! Why you think I'm saying the drugstore on Third?",2,"They had a whole aisle, diapers too, we're rinsing 'em in a bucket, it's disgusting",1,"I'll go, you keep her quiet",2,"If you're not back by dark I'm taking her to your mama's, I don't care what you say"}},
{"fw_ld5_pharmacy_a007","plan",2,"reg=civilian,family,worker,rescue|day=6,200|mood=grim",{1,"Dale's leg is red up past the knee and he won't say how bad it hurts",2,"Tylenol won't touch that, he needs antibiotics",1,"Only drugstore I know is past the goddamn water tower",2,"That end of town's crawling, you know it is",1,"Then we go early and slow, I ain't watching that leg get worse"}},
{"fw_ld5_pharmacy_a008","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=calm",{1,"Front shelves'll be picked over, the good stuff's behind the counter",2,"Locked cabinet, the pharmacist wore the key on a string around his neck",1,"Great, so we need him or a hammer",2,"Hammer, I'm not asking a dead man for his keys",1,"Don't say it like that",2,"Like what? It's the truth, bring a hammer, I'll bring a bag"}},
{"fw_ld5_pharmacy_a009","plan",3,"reg=civilian,family,worker,rescue|mood=calm",{1,"The big drugstore out on Dixie's got a pharmacy twice the size of Pruitt's",2,"And a parking lot full of cars nobody's coming out of, I drove past",3,"Pruitt's",1,"Pruitt's has a locked back room and nobody to ask",3,"Pruitt's, majority wins, shut up"}},
{"fw_ld5_pharmacy_a010","plan",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"Aspirin, Pepto, that pink stuff for the baby's gums, I wrote it on my arm",2,"You wrote it on your arm?",1,"Left my paper at the house, I'm not going back for paper",2,"Lemme see, oh Jesus, your handwriting, that says peppers"}},
{"fw_ld5_grocery_a011","plan",2,"reg=civilian,family,worker,rescue|day=0,8|mood=fear",{1,"IGA's shelves are empty, everybody says so",2,"The shelves are, the stockroom ain't, NOBODY thinks about the stockroom",1,"How the hell d'you know?",2,"Stocked there two summers, back's floor to ceiling cases, I'll show you where",1,"Then why the hell are we still eating crackers?"}},
{"fw_ld5_grocery_a012","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"No cart, no wagon, how are we carrying it?",2,"Pillowcases, I got six off the beds",1,"My mother'd die, canned beans in her good pillowcases"}},
{"fw_ld5_grocery_a013","plan",2,"reg=civilian,family,worker,rescue|mood=grim",{1,"Whatever you do, don't open the damn coolers in the back",2,"I-- I know, Boyd's wife said you can smell it from the lot",1,"So cans and boxes, nothing that needed ice",2,"Bandana over the nose",1,"Ten minutes, in and out, NOBODY browses"}},
{"fw_ld5_grocery_a014","plan",2,"reg=civilian,family,worker,rescue|x2=m|day=0,14|mood=funny",{1,"Ray says he don't need coffee and he's been walking into walls since the weekend",2,"I heard that",1,"You hear EVERYTHING but your own headache, we're getting you Folgers",2,"A can of Folgers, fine, I'll carry it myself"}},
{"fw_ld5_grocery_a015","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Carl would crawl through hell for a pack of Winstons",2,"Registers are right up front, I'll be quick about it",1,"The man's got two boys to feed and he wants cigarettes",2,"He wants a cigarette so he don't strangle somebody, that's the trade",1,"Get Marlboros too, the red ones, for Pete",2,"Who the hell's Pete, now it's the whole camp?!"}},
{"fw_ld5_grocery_a016","plan",2,"reg=family|mood=calm",{1,"Beans, rice, flour, lard, Mamaw says she can cook anything off a sack",2,"Sacks are heavy, who's hauling fifty pounds of rice?",1,"You are, you're the one eating it",2,"Mamaw's the only one in this family that's right about food, fine"}},
{"fw_ld5_grocery_a017","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Dog's eating better than we are",2,"He found a can of dog food, he ain't complaining",1,"Store's got a whole aisle of it, bring him, he'll find the good aisle quicker than us"}},
{"fw_ld5_grocery_a018","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"There's a Pepsi truck parked behind the Kroger, saw it from the overpass",2,"Still loaded?",1,"Sitting low on its springs, so yeah",2,"A warm Pepsi, God, I'd drink it out of a puddle",1,"Warm's a miracle, I'm bringing a straw"}},
{"fw_ld5_grocery_a019","plan",2,"reg=civilian,family,worker,rescue|day=1,12|mood=fear",{1,"Everybody in the county's going to the same grocery, that's the problem",2,"So we hit the little store at the crossroads",1,"It's chips and beer, that's about it",2,"Chips and beer is supper, and NOBODY's fighting us for it"}},
{"fw_ld5_grocery_a020","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=angry",{1,"I still remember how fast our pantry emptied. Two days of peaches and arguing",2,"You blamed the kids, like a case of peaches was ever going to last",1,"I was scared. Kept saying we'd find another case of something",2,"And I said, anything but peaches",1,"Apples, pears, a pineapple. We made a whole imaginary shopping list",2,"Better than arguing over whose fault hunger was"}},
{"fw_ld5_grocery_a021","plan",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"Those little jars of baby food, the peaches, the pears, I'm telling you",2,"You ate baby food?",1,"Ate a whole jar standing in the aisle, best thing I ever put in my mouth",2,"Then we get a case for the baby and a case for you"}},
{"fw_ld5_grocery_a022","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Everything at the Kroger's gonna say best by '91",2,"Who's checking?",1,"Nobody, it's a Vienna sausage, it was never fresh in the first place",2,"Then we eat the whole shelf, I'm done being picky",1,"Yeah, yeah, pick a can, any can, I'm hungry"}},
{"fw_ld5_vote_a023","plan",4,"reg=civilian,family,worker,rescue|mood=funny",{1,"Vote then, Kroger or the IGA",2,"Kroger",3,"IGA",4,"I'm hungry, either",1,"That's-- that's not a vote, Dale",4,"Most honest one you're gonna get"}},
{"fw_ld5_gas_a024","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=calm",{1,"Pumps are dead, so we pull it out of the cars",2,"With what?",1,"Garden hose, twelve feet of it, you suck till you taste it",2,"Did that once, tasted it a week, you can have the honor"}},
{"fw_ld5_gas_a025","plan",2,"reg=civilian,family,worker,rescue|day=0,20|mood=calm",{1,"Nobody's touched the old Marathon on 31W, the pumps are dead, why would they",2,"Everybody stares at the dead pumps and forgets the damn tank under the lot",1,"There's a hand crank round the back, from when the power went out in '87",2,"You remember that?",1,"I cranked it myself, nine hours, my arm didn't work till Tuesday"}},
{"fw_ld5_gas_a026","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=angry",{1,"We keep going in circles, none of us know these back roads",2,"Every gas station's got a map rack by the register",1,"A real map? Jesus, I forgot those exist",2,"Rand McNally, I'll grab two, one for the glove box, one for you to spill coffee on",1,"And a Coke",2,"Buy your own Coke, they're free now, dummy"}},
{"fw_ld5_gas_a027","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=fear",{1,"Generator's coughing, it wants diesel, only pump's behind the damn truck stop",2,"Truck stop had a lunch crowd Friday, who's still in there?!",1,"Don't-- don't know, I'm not asking",2,"Well I'm asking! You ain't sending me in blind"}},
{"fw_ld5_gas_a028","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Little station by the church still has a candy rack, and Dad's Skoal behind the register",2,"Skoal, Sharon? We're risking a trip for Skoal?",1,"He's been chewing toothpicks since Friday, he's mean, I want the Skoal",2,"Fine, but you're carrying, I ain't got the hands",1,"Deal, and I'll carry the candy too, the good kind, the sour ones"}},
{"fw_ld5_gas_a029","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=fear",{1,"Old man lives behind that Shell, got a twelve-gauge, so we knock first",2,"Knock first, like Girl Scouts?",1,"That or he shoots us, so yeah",2,"Then I'm bringing the cobbler, it's all I got that looks friendly"}},
{"fw_ld5_gas_a030","plan",2,"reg=civilian,family,worker,rescue|day=4,40|mood=grim",{1,"Four propane tanks in the cage behind the Gas-N-Go, I walked past 'em last week",2,"Good, the stove's about empty, we been eating beans cold",1,"They're heavy, forty pounds a tank",2,"Wagon, two trips, I'm not leaving propane sitting out there",1,"Two trips means two chances to meet somebody",2,"Then one trip, four tanks, we make the damn wagon work, I'll push"}},
{"fw_ld5_gas_a031","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=fear",{1,"Truck stop on the interstate has CBs, maps, showers, a hundred trucks",2,"And however many drivers",1,"CB would tell us what's going on everywhere in a day",2,"Daylight only, park a mile off, walk in"}},
{"fw_ld5_gas_a032","plan",2,"reg=civilian,family,worker,rescue|x1=m|mood=calm",{1,"Frank's boy works the Marathon, he's got keys to the back",2,"Where's he now?",1,"No idea, I called his mama's, phone's dead",2,"Then we break in anyway, forget Frank's boy"}},
{"fw_ld5_hardware_a033","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=fear",{1,"Hobbs Hardware's got plywood stacked out back, a whole stack",2,"For what?",1,"The damn windows! You hear 'em at night, I want boards up, like yesterday",2,"Nails, and a hammer that ain't missing half its handle",1,"Already wrote it down, wrote it on my hand, look"}},
{"fw_ld5_hardware_a034","plan",2,"reg=civilian,family,worker,rescue|x1=m|day=2,30|mood=angry",{1,"All I want is one pair of damn bolt cutters",2,"What for?",1,"Gate at the feed store, Larry's got a pallet of dog food behind it",2,"Larry left town Friday, Walt, it ain't--",1,"I know it ain't, I just wanna cut something, I'm tired of knocking"}},
{"fw_ld5_hardware_a035","plan",2,"reg=worker|mood=calm",{1,"All we got for cutting is steak knives, I hate it",2,"Steak knives is what you got",1,"Hobbs sells a splitting maul, three feet of handle, I'd sleep better holding that",2,"You'd sleep better, Rita'd sleep better, fine, Hobbs it is"}},
{"fw_ld5_hardware_a036","plan",2,"reg=civilian,family,worker,rescue|day=3,40|mood=sad",{1,"My sneakers are shot, I feel every rock out there",2,"Hobbs has work boots in the back, steel toe, the real ones",1,"In summer? My feet'll cook",2,"So they cook, mine are already blistered, get wool socks too"}},
{"fw_ld5_hardware_a037","plan",2,"reg=civilian,family,worker,rescue|day=5,40|mood=calm",{1,"I need a Coleman lantern and a gallon of that white fuel",2,"We got flashlights",1,"Flashlights are dead in two days, a lantern burns all night",2,"Since when are you the camping expert",1,"Since my uncle dragged me to Land Between the Lakes, and get mantles, no mantle no light"}},
{"fw_ld5_hardware_a038","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=grim",{1,"They hit the damn hardware store Friday night, I heard the glass from the porch",2,"Then it's picked over, we're wasting the trip",1,"Nobody takes the little stuff, hinges, hooks, rope",2,"You wanna build a barn?",1,"I wanna HAVE rope, you'd be surprised how often"}},
{"fw_ld5_hardware_a039","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"D batteries, we're down to four, the damn flashlight eats two a night",2,"Hardware, grocery, the little drugstore, anywhere",1,"Hardware's closest, they keep 'em in a rack by the register",2,"Take the radio so we can test 'em right there, I'm not buying dead ones"}},
{"fw_ld5_hardware_a040","plan",3,"reg=civilian,family,worker,rescue|day=4,30|mood=funny",{1,"There's a generator at Hobbs, brand new, still in the box",2,"It weighs a hundred and fifty pounds, Dale, how are we moving it?",1,"Three guys and a hand truck and a bad attitude",2,"And gas to run it, don't forget that part",3,"Why the hell's it always the dumb parts that matter"}},
{"fw_ld5_hardware_a041","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=fear",{1,"We need a padlock, a real chain, something to lock the damn gate with",2,"Park the truck in front of it",1,"Truck's gone, Frank took it Friday, remember?",2,"Then grab the damn chain, Hobbs keeps it on a spool by the foot"}},
{"fw_ld5_school_a042","plan",2,"reg=civilian,family,worker,rescue|day=0,8|mood=fear",{1,"We check the school first, I know it's stupid, I just gotta--",2,"Nobody-- nobody said it's stupid",1,"She was at summer reading Friday, if she got scared she'd hide, she always hides under a table",2,"...We go, but we go quiet, if she's not there we don't stay looking all--",1,"I know, I KNOW"}},
{"fw_ld5_school_a043","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=calm",{1,"High school cafeteria's got a walk-in and a pantry, and #10 cans, the big ones",2,"Like a gallon?",1,"Everything by the gallon, the lunch ladies stock up for fall",2,"God bless lunch ladies",1,"I'll carry two, you carry two, nobody plays the big man"}},
{"fw_ld5_school_a044","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=calm",{1,"Maybe they put people in the gym",2,"Who's they?",1,"The Army, anybody, it's what I'd do, cots, bathrooms, right there",2,"I'd rather find out than sit here guessing",1,"Yeah, me too, shit, me too"}},
{"fw_ld5_school_a045","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Six school buses behind the elementary, I counted",2,"Keys?",1,"Drivers hang 'em on a board in the garage office",2,"Even one with gas and that's twenty people out of here",1,"Even two, three, but who the hell's gonna drive it"}},
{"fw_ld5_school_a046","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=grim",{1,"Middle school nurse had a whole closet of first aid, my boy broke his arm there once",2,"Gauze, ice packs, those little wrist braces",1,"Better than the nothing we got",2,"It's something, get your goddamn shoes on"}},
{"fw_ld5_school_a047","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"Science lab at the high school keeps bleach and rubbing alcohol, all of it",2,"For the water?",1,"For everything, I ain't drinking that creek till it's treated",2,"Lab's on the second floor, I hate that stairwell"}},
{"fw_ld5_school_a048","plan",2,"reg=civilian,family,worker,rescue|day=5,200|mood=funny",{1,"Elementary's got a six-foot fence round the whole playground, one gate",2,"You counted that",1,"Something to do, there's nothing else to do",2,"One gate... yeah, I could sleep behind a fence like that, let's look at it"}},
{"fw_ld5_church_a049","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Mount Zion's got a food pantry in the basement, the church ladies kept it full",2,"I gave to that pantry every Christmas, now I'm gonna rob it",1,"We're not robbing it, we're borrowing",2,"Borrowing! From the Lord!",1,"He's got plenty, shit, we got nothing"}},
{"fw_ld5_church_a050","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=fear",{1,"Pastor Wells had a generator and a shortwave, he told us Sunday",2,"You think he's still there?",1,"I don't know, but he never turned that radio off",2,"We-- we knock, and if nobody answers we go, I'm not breaking a pastor's door down"}},
{"fw_ld5_church_a051","plan",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"Fellowship hall's got a stove big enough to cook for the whole street",2,"We could feed thirty",1,"Bring flour and lard, nobody makes biscuits like you",2,"I'll make biscuits, Lord help me, I'll make two hundred"}},
{"fw_ld5_church_a052","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"Church van's still in the lot, I saw it from the road, keys are in the office",2,"Does it run?",1,"Deacon Hollis drove it last Sunday, it ran then",2,"Last Sunday's a long time ago now"}},
{"fw_ld5_church_a053","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=fear",{1,"Thick walls, one room, we hide in the church till it blows over",2,"The bell, though, one wrong rope, the whole county knows we're there",1,"I'll tape the clapper, my daddy showed me",2,"Tape it twice, I'm NOT dying to a hymn"}},
{"fw_ld5_church_a054","plan",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"Mrs. Wells ran out of her insulin, she's been sleeping in a pew",2,"So ask at the parsonage, the pastor probably kept some",1,"If the pastor's even there",2,"I'll go, I know where he hides the spare key, I mowed his yard ten years"}},
{"fw_ld5_police_a055","plan",2,"reg=civilian,family,worker,rescue|day=0,8|mood=fear",{1,"County station's got the guns, somebody oughta have 'em before the wrong somebody does",2,"Somebody like us?",1,"Somebody better than whoever shows up if we don't",2,"We knock first, and if a deputy's in there we explain ourselves"}},
{"fw_ld5_police_a056","plan",2,"reg=civilian,family,worker,rescue|day=0,8|mood=fear",{1,"What if they're still in there, deputies, holed up with the shotguns?",2,"Then they tell us to go home",1,"We, we ain't got a home, we got a garage with a leaky water heater",2,"We wave a white rag and holler, I ain't getting shot to find out"}},
{"fw_ld5_police_a057","plan",2,"reg=civilian,family,worker,rescue|x2=m|day=3,30|mood=funny",{1,"County jail's got bars on every window and walls a foot thick",2,"It's also got forty cells and whoever they locked up Friday",1,"We sleep up front by the desk, the cells are in back",1,"And the break room's got a coffee machine",2,"You ain't sleeping in a jail for a coffee machine, Donnie"}},
{"fw_ld5_police_a058","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Dispatch has a base radio, a scanner, a map of the whole county on the wall",2,"If the power's on we could hear who's alive",1,"They kept a generator in the garage for storms, I'd bet",2,"I'd rather listen to a scanner than guess, let's go"}},
{"fw_ld5_police_a059","plan",2,"reg=civilian,family,worker,rescue|day=5,200|mood=grim",{1,"Evidence room's got the cash, the drugs, nobody to guard it",2,"I don't want the cash",1,"Me either, I want the radios, the vests are in the same locker",2,"Vests, yeah, I'd take a vest"}},
{"fw_ld5_fire_a060","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Station Two's got an engine, an engine's got a tank, that's like a thousand gallons",2,"A thousand gallons nobody's using",1,"Clean water for a month if we can work the pump",2,"Don't know the damn pump but the Chief's kid does, he's at the church"}},
{"fw_ld5_fire_a061","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"Turnout coats, the thick yellow ones, nothing's biting through that",2,"You wanna wear a fire coat in summer?",1,"I wanna be alive in summer, I'll sweat like a hog",2,"Fine",2,"I'm taking the helmet too, I like the helmet"}},
{"fw_ld5_fire_a062","plan",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"The firehouse I knew had bunks and a kitchen and a TV room",2,"Probably nothing worth watching even then",1,"There was a couch. That's the part I keep remembering",2,"A couch, God. I'd settle for remembering how that felt"}},
{"fw_ld5_fire_a063","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=grim",{1,"Firehouse has a base radio, Sam told me, the volunteer lieutenant",2,"Could we hear anybody on it?",1,"County was all over it Friday night, I don't know about NOW",2,"We go listen, it's more than we're doing here, damn it"}},
{"fw_ld5_fire_a064","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Firehouse has a pole, you slide down from the bunks",2,"We're not sliding down a pole",1,"I'm saying we sleep up top and if something comes, I slide",2,"Dale, you'd break both legs on that pole, we all know it"}},
{"fw_ld5_diner_a065","plan",2,"reg=civilian,family,worker,rescue|x2=m|mood=grim",{1,"No, no way, I'm not going in that kitchen",2,"It's the dry storage I want, nobody's making you open the freezer",1,"You-- you can smell it from the parking lot, Wayne!",2,"We go in the back way, rice, flour, sugar, that's all, five minutes",1,"...Fine, but I'm holding my breath the whole time, I'm not talking"}},
{"fw_ld5_diner_a066","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=funny",{1,"Dairy Bar's got ice cream",2,"It's July, the freezer's been off since Saturday",1,"It's SOUP now, but it's chocolate soup",2,"I'd drink it",1,"Me too, shit, right out the tub"}},
{"fw_ld5_diner_a067","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Ruth lives above the diner, always has, forty years",2,"So she's still up there or she's not",1,"If she's not there's a pantry and a deep freeze, Ruth never bought less than a hundred pounds of anything",2,"And if she is?",1,"I knock, I walk her to the church, I ain't leaving Ruth, I don't care what you say"}},
{"fw_ld5_diner_a068","plan",2,"reg=civilian,family,worker,rescue|day=5,40|mood=funny",{1,"Cooking oil, gallon jugs of it, the steakhouse had a whole shelf",2,"What the hell are we gonna do with oil?",1,"FRY! I wanna fry something, I ain't had anything fried since Friday, I'm losing my goddamn mind",2,"We got nothing to fry",1,"We'll find something, a fish, a shoe, I don't care"}},
{"fw_ld5_diner_a069","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=warm",{1,"Dot's keeps a key under the ceramic frog by the back step, everybody knows",2,"Everybody? I didn't know",1,"I've been eating her pie since I was nine, I know where everything is",2,"I want her pie",1,"If there's any left it's a fossil by now, but yeah, let's go look"}},
{"fw_ld5_diner_a070","plan",2,"reg=worker|day=2,30|mood=calm",{1,"Plant cafeteria stocks food for three shifts, freezer room, dry room",2,"Plant's six miles out",1,"We got a van and nothing else to do all week",2,"We don't tell Teddy's crew, I ain't splitting it with them bastards"}},
{"fw_ld5_diner_a071","plan",2,"reg=civilian,family,worker,rescue|x1=f|day=0,8|mood=fear",{1,"It was packed Friday, the whole dining room, the lunch--",2,"I know, Marcy",1,"So how many are still in there?!",2,"I'm NOT going through the front, there's a loading dock round the back, one way in, one way out"}},
{"fw_ld5_house_a072","plan",2,"reg=civilian,family,worker,rescue|day=0,12|mood=calm",{1,"The yellow house on the corner, the one with the swing, they left Friday, I watched the truck go",2,"So it's empty and probably stocked",1,"Garden in back, you can see the tomatoes from the street",2,"Tomatoes, God, real food, we go now before the birds get 'em"}},
{"fw_ld5_house_a073","plan",2,"reg=civilian,family,worker,rescue|x1=f|mood=sad",{1,"I can't go in people's houses, it ain't right",2,"They're not coming back, Pat",1,"You don't know that",2,"No",2,"I don't, so we leave a note, who we are, what we took, if they come back they'll know",1,"...A note, yeah, okay, I can do a note"}},
{"fw_ld5_house_a074","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=fear",{1,"Knock first, always knock first",2,"On a house that's been quiet four days?!",1,"Somebody could be in there, scared, with a gun",2,"Then YOU knock and I stand behind the truck, how's that"}},
{"fw_ld5_house_a075","plan",2,"reg=family|day=3,40|mood=warm",{1,"Old Mr. Tatum used to grow a garden the size of a football field",2,"Is he still out there?",1,"I saw chimney smoke Tuesday. Doesn't tell me who's there now",2,"If we ever meet him again, I hope we've something useful to offer"}},
{"fw_ld5_house_a076","plan",2,"reg=civilian,family,worker,rescue|day=1,14|mood=fear",{1,"The trailer across the creek has a dog that won't quit barking",2,"Then somebody's feeding it, or somebody's in there",1,"Or the dog's the only one left",2,"God",2,"don't say that, we go look, if it's the dog we bring the dog"}},
{"fw_ld5_house_a077","plan",2,"reg=civilian,family,worker,rescue|mood=grim",{1,"Big house up on the ridge, you hear a generator at night",2,"Somebody's running it",1,"Somebody NOT scared of noise, which scares me",2,"We go look in daylight, hands where they can see 'em"}},
{"fw_ld5_house_a078","plan",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"I wanna go home, just for an hour, I left the album on the piano",2,"What album?",1,"The wedding one, it's the only copy, my mother had the negatives",2,"...Okay, we go, one hour, if the street's bad we turn around, no arguing"}},
{"fw_ld5_house_a079","plan",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"Mrs. Hargis put up forty jars of green beans in June, she told me at the mailbox",2,"Her cellar's got to be full",1,"If she's gone she'd want us to have 'em, she fed half of Rosewood one bad winter",2,"We eat green beans, I say thank you out loud when we go in"}},
{"fw_ld5_house_a080","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=angry",{1,"We pick one house, ONE, we ain't going door to door",2,"Which one?",1,"Third on the left, no cars in the drive, curtains shut, NOBODY's been there for days",2,"Shut curtains means somebody shut 'em, I say the fifth one, it's got a fence",1,"Fence means dog, we're doing the third, I'm sick of this goddamn arguing"}},
{"fw_ld5_house_a081","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"My uncle's hunting cabin is out past Ekron, no neighbors for three miles",2,"Does it have a well?",1,"Hand pump out back, woodstove, rack of canned deer meat in the pantry",2,"Then why the hell are we sitting here! Pack the truck"}},
{"fw_ld5_clinic_a082","plan",2,"reg=civilian,family,worker,rescue|day=0,8|mood=fear",{1,"The free clinic by the post office, they gave my girl her shots there",2,"It'll be packed",1,"It was packed Friday, I saw the line from the bridge, I figure it's nothing now",2,"Nothing but what? You don't know what's in there"}},
{"fw_ld5_clinic_a083","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=grim",{1,"Rosewood Manor's got a nursing home with a medicine room and a hundred beds",2,"And a hundred people who couldn't leave",1,"I know, I know, I been thinking about it two days, I can't stop",2,"We go fast, and nobody goes in alone, nobody"}},
{"fw_ld5_clinic_a084","plan",2,"reg=civilian,family,worker,rescue|day=5,200|mood=funny",{1,"Vet's got amoxicillin, same stuff your doctor gives you, just a bigger bottle with a dog on it",2,"You're gonna eat dog pills",1,"If it clears up Dale's leg I'll eat the dog",2,"Easy! Let's just get the pills"}},
{"fw_ld5_clinic_a085","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=sad",{1,"Dr. Mercer's office, he always had those little bottles of the good painkillers",2,"For Pop's tooth?",1,"He's been chewing on one side three days and he won't say a word",2,"We go, we get him something, even if I have to hold him down"}},
{"fw_ld5_clinic_a086","plan",2,"reg=civilian,family,worker,rescue|day=0,8|mood=fear",{1,"Hardin Memorial's the closest real hospital, twelve miles",2,"Twelve miles of EVERYBODY heading the same way",1,"We, we could walk the railroad bed, nobody's on it",2,"If there's even a doctor, I ain't walking twelve miles to read a sign on a locked door"}},
{"fw_ld5_clinic_a087","plan",2,"reg=rescue|role=rescue_medical|day=0,14|mood=calm",{1,"If we get into the ER supply room I can get sutures, saline, a real splint",2,"Where's the key?",1,"It's a code, 1-1-0-4, same code twelve years, I used to sign my name under it",2,"Let's go, I'd rather stitch Dale up right than watch him bleed through a damn bandana"}},
{"fw_ld5_clinic_a088","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=warm",{1,"Doc Landry lives on Poplar, he delivered half this town",2,"Think he stayed?",1,"He's seventy-three with a bad hip, he's not going anywhere, he's at home with his bag",2,"We go get him and bring him along, a doctor's worth more than any drugstore"}},
{"fw_ld5_feed_a089","plan",2,"reg=family|day=3,40|mood=warm",{1,"Tuttle's Feed and Seed has seed packets, a whole rack of 'em",2,"In summer?",1,"Turnips, Mamaw says turnips go from seed to supper in sixty days, even in bad dirt",2,"Sixty days... that's September",1,"I know what month September is! Just get the packets, and a shovel"}},
{"fw_ld5_vfw_a090","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=fear",{1,"VFW hall's got a kitchen, and the old boys keep rifles over the bar",2,"Old boys with rifles, that sounds like a warning to me",1,"They know us, we been to every fish fry since 1980",2,"You go first, hands up, holler your name",1,"I'll holler yours too, we ain't doing this blind"}},
{"fw_ld5_liquor_a091","plan",2,"reg=civilian,family,worker,rescue|x1=m|day=2,30|mood=funny",{1,"I'm not looting a liquor store",2,"Nobody said looting, it's medicine",1,"Medicine?",2,"Bourbon's an antiseptic, my granddaddy poured it on everything, wounds, dogs, toothaches",1,"...Maker's Mark for the leg, I can hold that thought"}},
{"fw_ld5_bar_a092","plan",2,"reg=worker|day=0,14|mood=calm",{1,"The Rusty Nail keeps a twelve-gauge under the bar, Big Earl showed me once",2,"And a walk-in full of beer that's warm by now",1,"Warm beer I can live with, it's the shotgun I want",2,"Earl's gonna be mad",1,"Earl's wherever Earl is, he ain't gonna miss it"}},
{"fw_ld5_auto_a093","plan",2,"reg=worker|x2=m|mood=angry",{1,"Truck's DEAD, battery's dead, nothing's moving till we get a new one, damn it",2,"Auto parts on Dixie's got a whole wall of 'em",1,"Jumper cables too, a fan belt, I'm tired of walking",2,"Walking never killed anybody",1,"It's killing my feet, Mitch! I'd like to ride somewhere!"}},
{"fw_ld5_sporting_a094","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=fear",{1,"Sporting goods has aluminum bats, a whole barrel by the register",2,"Bats, yeah, better than what we got",1,"And fishing line, tarps, those little camp stoves",2,"And ammo if anybody left any, don't say that too loud"}},
{"fw_ld5_surplus_a095","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"The Army-Navy store I used to visit in E-town sold boots, canteens, ponchos, ammo cans",2,"Ammo cans! You can keep anything dry in those",1,"And the ponchos, I'm sick of being wet",2,"Worth remembering if we're ever nearby. Not worth promising it'll still have stock"}},
{"fw_ld5_library_a096","plan",2,"reg=civilian,family,worker,rescue|day=5,200|mood=calm",{1,"Library's got the county map and a whole shelf of canning books",2,"A book's gonna feed us now?",1,"A book's gonna tell us how not to poison ourselves, that's the next problem",2,"Books, then, take a couple for the kids, I'm sick of the same Bible stories"}},
{"fw_ld5_optic_a097","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"I sat on my glasses, I can't tell a can of peaches from motor oil",2,"You-- you ate motor oil?",1,"I ate SOMETHING, it was brown!",2,"There's an eye doctor next to the bank, frames in the front window",1,"Then take me there, I don't care what they look like"}},
{"fw_ld5_bank_a098","plan",2,"reg=civilian,family,worker,rescue|x1=m|day=0,14|mood=funny",{1,"I say we hit the bank",2,"For what, money?",1,"I don't know, habit, always wanted to",2,"It's paper, Mickey, you can't eat it, it don't even burn good",1,"Fine, grocery, but I'm telling people I robbed the bank"}},
{"fw_ld5_bakery_a099","plan",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"Bakery on Main smelled like bread every morning, I walked past it twenty years",2,"It won't smell like bread now",1,"I, I know, I just wanna see it, there might be flour in the back",2,"Flour, sure, but you're gonna cry, I ain't carrying you",1,"I'm not gonna cry, shut up"}},
{"fw_ld5_motel_a100","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=warm",{1,"Motel out on the highway has twenty rooms and every one's got a bed",2,"A bed! A real mattress!",1,"Lock on the door and a chair to jam under it",2,"I'd sleep like the dead, sorry, bad choice of words, like a baby"}},
{"fw_ld5_truckstop_a101","plan",2,"reg=civilian,family,worker,rescue|day=5,200|mood=funny",{1,"I'd kill for a shower",2,"Truck stop's got showers, six of 'em, a little bar of soap in each",1,"Hot?",2,"Probably cold",1,"I don't care, get me there, I smell like a barn"}},
{"fw_ld5_lumber_a102","plan",2,"reg=worker|x2=m|day=2,30|mood=calm",{1,"Lumber yard's got two-by-fours stacked to the ceiling, we could wall off the whole back",2,"And a forklift, I used to drive one",1,"You're not driving a forklift down the road, Roy",2,"Watch me, two pallets, one attitude"}},
{"fw_ld5_orchard_a103","plan",2,"reg=civilian,family,worker,rescue|day=2,14|mood=warm",{1,"Peaches are coming ripe at the Yates orchard, I saw 'em from the road",2,"Real peaches? Not a can?",1,"Real ones, soft, with the fuzz, nobody's picked 'em",2,"God",2,"I'd walk ten miles, I'm gonna eat till I'm sick"}},
{"fw_ld5_dollar_a104","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Dollar store's got candles, batteries, canned soup, it was all a dollar",2,"Everything was a dollar",1,"Nothing costs anything now, shit, we're rich",2,"Rich in candles, let's go"}},
{"fw_ld5_funeral_a105","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Funeral home's got a hearse, full tank, nobody's put three miles on it",2,"We-- we ain't driving a hearse, NO",1,"Bench seat for six, never been in a wreck",2,"People'll see us coming and think we're dead",1,"Then they leave us alone, Dale, drive the hearse"}},
{"fw_ld5_poolclub_a106","plan",2,"reg=civilian,family,worker,rescue|day=4,40|mood=calm",{1,"Country club's got a pool, six feet deep, green by now but it's water",2,"Not for drinking",1,"For washing, for the toilets, for not smelling like this",2,"Sold, we bring buckets, and the clubhouse has a kitchen, I bet"}},
{"fw_ld5_walmart_a107","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=fear",{1,"Wal-Mart's got everything, that's why it's a death trap",2,"Everybody in Radcliff went there Friday night",1,"So we don't go, we go around, the little stores",2,"Little stores are fine, I'm NOT going near that lot"}},
{"fw_ld5_barber_a108","plan",2,"reg=civilian,family,worker,rescue|x1=m|day=5,200|mood=funny",{1,"I look like a bear that lost a fight",2,"Barbershop on Elm has clippers and a straight razor and a mirror",1,"No power, though",2,"A razor don't need power, Hank, sit still, I'll do it"}},
{"fw_ld5_pool_a109","plan",2,"reg=civilian,family,worker,rescue|day=2,20|mood=funny",{1,"Pool hall on Third has cue sticks, solid maple, four feet of it",2,"You wanna fight with a pool cue",1,"I wanna fight with SOMETHING, it's better than a spatula",2,"Fine, and chalk, we need something to write notes on the wall"}},
{"fw_ld5_mill_a110","plan",2,"reg=family|day=5,200|mood=calm",{1,"Grain elevator by the tracks has corn, whole kernel, not even wet",2,"We can't eat whole kernel",1,"Mamaw's got a hand mill from her mother, she grinds it, that's cornmeal",2,"Then that's bread! Actual bread, load the wagon"}},
{"fw_ld5_bowling_a111","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=funny",{1,"Bowling alley's got a snack bar, a roof, forty bathroom stalls",2,"You wanna sleep in a bowling alley",1,"Big open room, you'd see ANYTHING coming down the lanes",2,"And free shoes, I been wearing these three days"}},
{"fw_ld5_junkyard_a112","plan",2,"reg=worker|day=5,200|mood=calm",{1,"Salvage yard on Pike's got fifty cars, half of 'em got gas in the tank",2,"Fifty, I'd like to see that",1,"We siphon, easy, nobody guards a junkyard",2,"Dogs, there's always a junkyard dog",1,"...Bring a pork chop"}},
{"fw_ld5_pawn_a113","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=fear",{1,"Pawn shop on Dixie's got guns, radios, a big old Zenith, ANYTHING",2,"That's-- that's where everybody's heading",1,"Then we're there before they are, get up",2,"I'm up, I'm up!"}},
{"fw_ld5_bait_a114","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Bait shop by the river's got hooks, line, a freezer full of nightcrawlers",2,"Nightcrawlers don't taste like nothing good",1,"Nightcrawlers are BAIT, you moron, for the catfish!",2,"Catfish, God, yes, I'd cry"}},
{"fw_ld5_waterplant_a115","plan",2,"reg=worker|day=2,30|mood=calm",{1,"Water plant's got a backup tank, ten thousand gallons, gravity fed",2,"Clean?",1,"Chlorinated last I knew, my cousin works there, he showed me the valve",2,"Then we go, I'm bringing every bucket in the county"}},
{"fw_ld5_daycare_a116","plan",2,"reg=civilian,family,worker,rescue|x1=f|mood=sad",{1,"The daycare on Walnut, I keep thinking about--",2,"Don't, Sue",1,"I remember cots and juice boxes in the back room. Doesn't mean they're there now",2,"I understand wanting to look. We'd have to check the place, not walk in expecting supplies",1,"I hear you"}},
{"fw_ld5_rv_a117","plan",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"RV lot out on the bypass, forty of 'em, every one's got a bed, a stove",2,"And a water tank",1,"And a lock that works from the inside, it's a motel with wheels",2,"Who's gonna drive it?",1,"Nobody, we SLEEP in it, one night, a real bed",2,"...I'd give a finger for a real bed"}},
{"fw_ld5_carlot_a118","plan",2,"reg=worker|mood=calm",{1,"Dealership's got new trucks, keys in the lockbox in the office, tanks topped off",2,"Topped off? You sure?",1,"Salesman told me, they do it so the test drive don't run dry",2,"We take two, one for people, one for stuff, I drive the red one"}},
{"fw_ld5_news_a119","plan",2,"reg=civilian,family,worker,rescue|day=4,40|mood=funny",{1,"The paper's got a printing press, we could put out a paper",2,"Nobody's reading",1,"They'd read it if it said where the food is, who's alive, what day it is",2,"...I'd read it, I'd read the funnies if there were funnies",1,"Then we write funnies too, I got a bad joke about a Kentucky colonel"}},
{"fw_ld5_dealer_a120","plan",2,"reg=worker|day=3,40|mood=calm",{1,"My uncle used to buy diesel and oil at the implement dealer",2,"What would we want with a tractor?",1,"Might pull a wagon through a field, if we found one that ran",2,"I grew up driving one. Finding a working one is the part I can't help with"}},
{"fw_ld5_greenhouse_a121","plan",2,"reg=family|day=5,40|mood=warm",{1,"I keep thinking about that greenhouse on Route 60. Tomatoes, peppers, little cucumbers",2,"You think somebody's still watering it?",1,"I don't know. I just remember how full it used to look",2,"If we ever find living plants, I'd rather leave some for the next person"}},
{"fw_ld5_laundry_a122","plan",2,"reg=civilian,family,worker,rescue|day=5,200|mood=funny",{1,"I smell like a wet dog that rolled in something",2,"Laundromat on Elm's got detergent, a whole shelf of little boxes",1,"And the change machine, I'm taking the quarters out of habit",2,"We wash in the creek and smell like soap for one day, God, that'd be a miracle"}},
{"fw_ld5_hotel_a123","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Old hotel on the square's got a lobby with a fireplace and a hundred keys on a board",2,"Hundred rooms, and a fire escape",1,"We pick one on the third floor, one stairwell, block the bottom with the piano",2,"With the PIANO! I knew there was a reason I liked that hotel"}},
{"fw_ld5_barn_a124","plan",2,"reg=family|mood=calm",{1,"Old tobacco barn out on Pike Road, hung with sticks, the whole thing smells like the seventies",2,"That smell's gonna get in our clothes",1,"That smell's the only thing left in this county that don't scare me",2,"One big door, a hundred gaps in the boards, I can see everything from inside, it's good"}},
{"fw_ld5_radio_b001","plan",3,"reg=civilian,family,worker,rescue|day=3,30|mood=grim",{1,"Three days in this garage and all we do is eat crackers and look at each other",2,"You got a better idea?",1,"Maybe a radio station somewhere around here, somebody's gotta be on the air, shit",3,"There's the little AM station past the high school, you can see the tower from the overpass",1,"That's where we go, I'd rather get shot at than sit here another goddamn day"}},
{"fw_ld5_radio_b002","plan",2,"reg=civilian,family,worker,rescue|hour=18,4|mood=calm",{1,"AM carries way farther after dark, my daddy used to pull in WHAS from the porch",2,"You can't get Louisville from here",1,"You can at night, it bounces off the sky or something, I ain't an engineer",2,"We try it, get the battery radio, climb the damn water tower if we have to"}},
{"fw_ld5_radio_b003","plan",2,"reg=worker|day=0,20|mood=calm",{1,"Every rig's got a CB, channel 19, truckers talk about everything all day",2,"Rigs are out on the interstate, half of 'em stuck",1,"Stuck means parked, parked means a battery somewhere, a radio on it",2,"That's a long walk for a maybe",1,"Every walk's a long one, at least this one's got a voice at the end"}},
{"fw_ld5_radio_b004","plan",2,"reg=civilian,family,worker,rescue|day=3,40|mood=calm",{1,"Orville Haney's got a ham rig in his garage and a tower in the yard like an antenna farm",2,"Is he even alive?",1,"Crazy old man, I'd bet money he's sitting in front of it right now talking to Japan",2,"So we go ask him what Japan says, I'm curious now"}},
{"fw_ld5_radio_b005","plan",2,"reg=family|day=0,10|mood=fear",{1,"Walt keeps one of those little battery TVs in his truck, I seen it",2,"What's on it, static?!",1,"Maybe, or maybe Channel 11's still on, they got a generator",2,"We ask Walt, and if he says no I'll trade him cigarettes"}},
{"fw_ld5_radio_b006","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Radio Shack in the strip mall's got scanners and antennas and a whole wall of batteries",2,"It's been picked over, I bet",1,"Nobody picks over a Radio Shack, it's the one store nobody thinks of",2,"I think of it, I just never go in, fine, let's see"}},
}
